use axum::{routing::get, Router};

#[tokio::test]
async fn issue_nested_fallback_regression() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new().nest("/nested", nested_routes).merge(other_router);

    let client = axum::test_helpers::TestClient::new(app);

    let res = client.get("/other").send().await;
    assert_eq!(res.text().await, "other");

    let res = client.get("/nested/some-route").send().await;
    assert_eq!(res.text().await, "nested");

    let res = client.get("/nested/foo").send().await;
    assert_eq!(res.status(), axum::http::StatusCode::NOT_FOUND);
    assert_eq!(res.text().await, "fallback");
}

